CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TABLE properties (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), name varchar(160) NOT NULL, address varchar(250) NOT NULL, city varchar(120) NOT NULL, postal_code varchar(12) NOT NULL, units integer NOT NULL CHECK(units>=0), kind varchar(20) NOT NULL CHECK(kind IN ('WEG','RENTAL','MIXED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE requests (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), title varchar(180) NOT NULL, description text NOT NULL DEFAULT '', requester varchar(120) NOT NULL, category varchar(30) NOT NULL, priority varchar(12) NOT NULL CHECK(priority IN ('LOW','NORMAL','HIGH','URGENT')), status varchar(20) NOT NULL DEFAULT 'OPEN' CHECK(status IN ('OPEN','IN_PROGRESS','WAITING','RESOLVED')), created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX ix_requests_property_status ON requests(property_id,status);
CREATE TABLE approvals (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), title varchar(180) NOT NULL, amount numeric(12,2) NOT NULL CHECK(amount>=0), requested_by varchar(120) NOT NULL, status varchar(20) NOT NULL DEFAULT 'PENDING' CHECK(status IN ('PENDING','APPROVED','REJECTED')), notes text NOT NULL DEFAULT '', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE meetings (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), title varchar(180) NOT NULL, meeting_date date NOT NULL, location varchar(180) NOT NULL, minutes text NOT NULL DEFAULT '', status varchar(20) NOT NULL DEFAULT 'PLANNED' CHECK(status IN ('PLANNED','HELD','MINUTES_DRAFT','FINALIZED')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resolutions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), meeting_id uuid NOT NULL REFERENCES meetings(id), resolution_no varchar(35) NOT NULL, wording text NOT NULL, announced_on date, result varchar(20) NOT NULL CHECK(result IN ('ADOPTED','REJECTED','PENDING')), challenged boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(meeting_id,resolution_no));
CREATE TABLE correspondence (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), property_id uuid NOT NULL REFERENCES properties(id), subject varchar(180) NOT NULL, body text NOT NULL, recipient varchar(180) NOT NULL, channel varchar(20) NOT NULL CHECK(channel IN ('EMAIL','LETTER','PORTAL')), status varchar(20) NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','READY','SENT')), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE activity (id bigserial PRIMARY KEY, entity_type varchar(40) NOT NULL, entity_id uuid NOT NULL, action varchar(40) NOT NULL, actor varchar(120) NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
